import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int n=sc.nextInt();int[]nums1=new int[n];for(int i=0;i<n;i++)nums1[i]=sc.nextInt();int m=sc.nextInt();int[]nums2=new int[m];for(int i=0;i<m;i++)nums2[i]=sc.nextInt();Deque<Integer>stk=new ArrayDeque<>();Map<Integer,Integer>mp=new HashMap<>();for(int v:nums2){while(!stk.isEmpty()&&stk.peek()<v)mp.put(stk.pop(),v);stk.push(v);}StringBuilder sb=new StringBuilder();for(int i=0;i<n;i++){if(i>0)sb.append(' ');sb.append(mp.getOrDefault(nums1[i],-1));}System.out.println(sb);}}
